def transform(grid):
    n, m = len(grid), len(grid[0])
    best = None
    for r in range(n - 2):
        for c in range(m - 2):
            counts = {}
            for i in range(r, r + 3):
                for j in range(c, c + 3):
                    v = grid[i][j]
                    if v:
                        counts[v] = counts.get(v, 0) + 1
            for color, count in counts.items():
                if best is None or count > best[0]:
                    best = (count, r, c, color)
    _, r, c, color = best
    return [[8 if grid[r+i][c+j] == color else 0 for j in range(3)] for i in range(3)]
