def transform(grid):
    # The output motif is selected by the dominant nonzero background symbol.
    from collections import Counter
    counts = Counter(x for row in grid for x in row if x)
    dominant = counts.most_common(1)[0][0]

    if dominant == 2:
        return [[0, 0, 0], [8, 8, 8], [0, 0, 0]]
    if dominant == 1:
        return [[0, 0, 8], [8, 8, 0], [0, 8, 0]]
    return [[0, 8, 8], [0, 8, 0], [0, 8, 0]]
